static mat2 ofs = mat2 ((1.0/uTexSize.x), 0.0 , 0.0 ,(1.0/uTexSize.y)) * 4.0;
static vec3 suncol = 1.0 + normalize(slow_roam_cos);
vec3 cloud(vec2 uv_in) { return (.2+(1.0 + audioLowSmooth)*.01/length(uv_in-sunpos)*suncol+(rand_preset.z-.5)*uv_in.y).xyz; }
shader_body {
vec2 uv1 = vec2(uv.x-0.5+q19,uv.y-0.5);//*uAspect.xy;
dx = texture(sampler_main,uv+ofs[0]) - texture(sampler_main,uv-ofs[0]);
dy = texture(sampler_main,uv+ofs[1]) - texture(sampler_main,uv-ofs[1]);
zz = vec2(dx.b,dy.b);
//clouds
zv = uTime*.06 ;
zv = uTime*.08+ .0*GetPixel(uv); //##
uv2 = 3.0 * uv1+ vec2(0.02*uTime,-.05*uTime);
n1 = tex3D(sampler_rand00,vec3 (uv2.x,uv2.y,zv)).b;
n2 = tex3D(sampler_rand00,vec3 (uv2.x * 2.0,uv2.y * 2.0,zv * 2.0)).b;
n3 = tex3D(sampler_rand00,vec3 (uv2.x * 4.0,uv2.y * 4.0,zv * 3.0)).b;
n4 = tex3D(sampler_rand00,vec3 (uv2.x * 8.0,uv2.y * 8.0,zv * 7.0)).b;
noise = n1 + n2 / 2.0 + n3 / 4.0 + n4 / 8.0 -1;
noise = pow(noise, 1.0 );
uv2 = uv1+noise*.1;
//*******************************
ret1 = cloud(uv2);
float k1 = .1;
ret = ret1*k1 / 2.0 + GetPixel(uv-.02*zz)*(1.0 - k1)-.01;
//ret = 0;
}

