float z,mask,water,rain;
float2 rs0, rs, uv0, uv1, uv2, uv3, uv4, uv5, uv_wat, uv_sky,
uv_stars, sunpos, uv_clouds;
float3 ret1, ret2, sun, sunshine;
static float trel = q10;
shader_body {
uv0 = uv;
float2x2 ang1 = float2x2 (_qb);
uv = mul((uv-.5),ang1)*.7*aspect.xy+.5+float2(q15,q16);
float2 center = float2 (.5,q11+.6+q12*(sin(uv.x*6+trel)*cos(uv.y*8+time*.6)));
rain = tex2D (sampler_noise_lq,float2(uv.x*4,uv.y)*.2-time);
rain += tex2D (sampler_noise_lq,float2(uv.x*4,uv.y)*.5-time);
//rain *= (rain >= 1);
rain *= 1*saturate(q20/2-abs(sin(uv0.x-time/4)));
uv1 = (uv-center+rain*.01);
mask = saturate(128*uv1.y);
z = .4/(uv1.y);
rs0.x = uv1.x * z; rs0.y = z ;
rs = float2 (rs0.x+time/4, rs0.y+time*4)*mask;
water = tex2D(sampler_noise_hq,rs) + tex2D(sampler_noise_hq,rs/4-time/8);
//water = pow(water/2,2);
water -= 1 ;
uv_sky = float2(uv.x,uv.y);
uv_wat = float2(uv1.x+.5,abs(.5-uv1.y))-.2*water/pow(z,.5);
ret1 = GetPixel(uv_sky+rain*.0)*(1-mask) + //Himmel
GetPixel(uv_wat)*mask/pow(z,.4)*2*(1-rand_preset.y) + //Wasser
rand_preset.y*
(1+rand_preset.x*water)*mask/z*float3(0,.1,.1); //Leuchten Wasser
ret1 *= (1+.2*rain);
ret = 1-exp(-pow(ret1,1.5)*8);
}

